<script setup lang="ts">import{ref,onMounted,watch,computed}from 'vue';import{useRouter}from 'vue-router';import{samples,loadBatches}from '../stores/samples';import{runs,loadRuns}from '../stores/runs';import{createRun}from '../api/runs';import{getFeasibility}from '../api/batches';import{canEdit}from '../stores/auth';
import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import BatchSelect from '../components/BatchSelect.vue';import RunTable from '../components/RunTable.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import FeasibilityPanel from '../components/FeasibilityPanel.vue';import type{FeasibilityDiagnostic}from '../types/domain';
const router=useRouter();const form=ref({name:'11月城区出行 · 代表性校准',batch_id:1,tolerance:.0001,max_iterations:500,cap_ratio:12});
const{error,busy,execute}=useTask();const diagnostic=ref<FeasibilityDiagnostic|null>(null);const checking=ref(false);const feasibilityError=ref('');
const refresh=()=>execute(async()=>{await Promise.all([loadBatches(),loadRuns()])});
// 预检独立于页面级错误：未登记目标等 422 只在表单内温和提示，不打断整页。
const checkFeasibility=async()=>{checking.value=true;feasibilityError.value='';try{diagnostic.value=await getFeasibility(form.value.batch_id,form.value.cap_ratio);}catch(e){diagnostic.value=null;feasibilityError.value=e instanceof Error?e.message:'可行性预检不可用，请先登记目标边际';}finally{checking.value=false}};
watch(()=>[form.value.batch_id,form.value.cap_ratio],checkFeasibility);
const submit=()=>execute(async()=>{const r=await createRun(form.value);await router.push('/results/'+r.id)});
onMounted(async()=>{await refresh();await checkFeasibility()});
const blocksRun=computed(()=>diagnostic.value?.status==='structurally_infeasible'||diagnostic.value?.status==='invalid_targets');
const applyMinimumCap=()=>{if(diagnostic.value?.minimum_cap_ratio)form.value.cap_ratio=Math.min(30,Number(diagnostic.value.minimum_cap_ratio.toFixed(3)))};</script>
<template><PageHeading index="04" title="一次可复算的权重迭代" subtitle="逐维调整类别权重，保留每一步残差及截断对收敛的影响。"/><ErrorNotice :message="error" @retry="refresh"/><div class="workbench"><form v-if="canEdit" @submit.prevent="submit"><h2>建立校准运行</h2><label>研究名称<input v-model="form.name" required minlength="2" maxlength="100"/></label><BatchSelect v-model="form.batch_id" :items="samples.batches"/><div class="form-grid"><label>归一残差容差<input v-model.number="form.tolerance" type="number" min=".000001" max=".05" step=".000001" required/></label><label>最多迭代次数<input v-model.number="form.max_iterations" type="number" min="1" max="2000" required/></label></div><label>权重上限 / 目标平均权重的倍数<input v-model.number="form.cap_ratio" type="number" min="1" max="30" step=".1" required/></label><div v-if="diagnostic" class="feas-inline"><FeasibilityPanel :diagnostic="diagnostic" :loading="checking"/><button v-if="diagnostic.status==='cap_insufficient'&&diagnostic.minimum_cap_ratio" type="button" class="link-button" @click="applyMinimumCap">采用最小可行倍数 {{diagnostic.minimum_cap_ratio}} →</button></div><p v-else-if="feasibilityError" class="method-note">{{feasibilityError}}</p><p v-else-if="checking" class="method-note">正在做联合可行性预检…</p><button class="primary" :disabled="busy||blocksRun">{{busy?'正在排队…':blocksRun?'预检未通过，不能提交':'提交后台校准 →'}}</button></form><aside><p class="eyebrow">METHOD / BOUNDED RAKING</p><h2>边际收敛，<br>不等于消除了全部偏差。</h2><p>每轮依次校准年龄组、出行方式和分区，再截断权重。运行前先做联合可行性预检，把“交叉结构无解、上限不足、暂未收敛”分开，不必等迭代耗尽才发现矛盾。</p><p>结构无解会列出矛盾类别；上限不足会给出最小可行倍数；预检可行但未达标才属于迭代问题。Kish有效样本量只反映权重离散的代价，不包含聚类、分层或未观测选择偏差。</p><p>未收敛运行可查看诊断，负责人不能批准交付。</p></aside></div><div class="section-heading"><h2>迭代档案</h2><button @click="refresh">刷新 ↻</button></div><RunTable :items="runs.items"/></template>
